	users    *UserStore
	products *ProductStore
	orders   *OrderStore
	reviews  *ReviewStore
}

// from user_handlers.go
func (s *Server) userRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /users", s.handleListUsers)
	mux.HandleFunc("GET /users/{id}", s.handleGetUser)
	mux.HandleFunc("POST /users", s.handleCreateUser)
	mux.HandleFunc("DELETE /users/{id}", s.handleDeleteUser)
}

// from user_handlers.go
func (s *Server) handleGetUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	u, ok := s.users.Get(id)
	if !ok {
		writeNotFound(w, "user", id)
		return
	}
	writeJSON(w, http.StatusOK, u)
}

// from respond.go
func writeJSON(w http.ResponseWriter, status int, data any) {
	writeRaw(w, status, dataEnvelope{Data: data})
}

// from user_store.go
// List returns all users sorted by ID.
func (st *UserStore) List() []User {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := make([]User, 0, len(st.items))
	for _, u := range st.items {
		out = append(out, u)
	}
	slices.SortFunc(out, func(a, b User) int { return strings.Compare(a.ID, b.ID) })
